import { initializeApp } from "https://www.gstatic.com/firebasejs/13.0.0/firebase-app.js";
import { createUserWithEmailAndPassword, getAuth, onAuthStateChanged, sendPasswordResetEmail, signInWithEmailAndPassword, signOut, updateProfile } from "https://www.gstatic.com/firebasejs/13.0.0/firebase-auth.js";
import { collection, doc, getDoc, getFirestore, onSnapshot, query, serverTimestamp, setDoc, updateDoc, where } from "https://www.gstatic.com/firebasejs/13.0.0/firebase-firestore.js";
import { BASE_INGREDIENTS } from "./base-ingredients.js";

const config=window.MAUGAINZ_SITE_CONFIG?.firebase||{};
const configured=Boolean(config.apiKey&&config.projectId&&config.appId);
const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const num=value=>Number(String(value??0).replace(',','.'))||0;
const round=(value,digits=1)=>Number(num(value).toFixed(digits));
const id=prefix=>`${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
const esc=(value='')=>String(value).replace(/[&<>'"]/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[ch]);
const norm=(value='')=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const localDate=(date=new Date())=>{const copy=new Date(date);copy.setMinutes(copy.getMinutes()-copy.getTimezoneOffset());return copy.toISOString().slice(0,10)};
const emptyMacros=()=>({calories:0,protein:0,carbs:0,fat:0,fiber:0});
const emptyPayload=()=>({version:6,recipes:[],customCategories:[],goals:{weightKg:85,goal:'gain',calories:3060,protein:170,carbs:394,fat:77},plans:[],shopping:[],unitSystem:'metric',dailyTargets:[],weights:[],vitamins:[],savedIngredients:[],trainingDays:[],diaryEntries:[]});
const friendCodeFor=uid=>uid.replace(/[^a-z0-9]/gi,'').slice(0,8).toUpperCase();
const units=['g','kg','ml','cl','dl','l','pc','tbsp','tsp','scoop'];
const meals=['Breakfast','Lunch','Dinner','Snack'];
const builtInCategories=['Breakfast','Post-workout','High calorie','Quick meal'];
const pieceWeights={eggs:50,banana:118,apple:180,avocado:150,tortilla:65,bread:38,garlic:3};
const i18n={
  en:{overview:'Overview',diary:'Diary',recipes:'Recipes',create:'Create',plan:'Plan',performance:'Performance',ingredients:'Ingredients',friends:'Friends',settings:'Settings',synced:'Synced',syncing:'Syncing…',error:'Sync issue',titles:{overview:'Command center',diary:'Food diary',recipes:'My cookbook',create:'Recipe studio',plan:'Meal & training plan',performance:'Performance control center',ingredients:'Ingredient library',friends:'Friends & sharing',settings:'Settings'}},
  nl:{overview:'Overzicht',diary:'Dagboek',recipes:'Recepten',create:'Maken',plan:'Planning',performance:'Prestaties',ingredients:'Ingrediënten',friends:'Vrienden',settings:'Instellingen',synced:'Gesynchroniseerd',syncing:'Synchroniseren…',error:'Synchronisatieprobleem',titles:{overview:'Controlecentrum',diary:'Voedingsdagboek',recipes:'Mijn kookboek',create:'Receptstudio',plan:'Maaltijd- en trainingsplan',performance:'Prestatiecentrum',ingredients:'Ingrediëntenbibliotheek',friends:'Vrienden en delen',settings:'Instellingen'}}
};
const tr=(en,nl)=>locale==='nl'?nl:en;
const recipeName=recipe=>locale==='nl'?(recipe.titleNl||recipe.title):recipe.title;
const ingredientName=item=>locale==='nl'?(item.nameNl||item.name):item.name;

let app,auth,db,currentUser=null,payload=emptyPayload(),authMode='login',locale=localStorage.getItem('maugainz-locale')||'en',previewMode=false;
let saveTimer=0,unsubscribeData=null,unsubscribeFriends=[],connections=[],shares=[];
let diaryMode='product',diaryDate=localDate(),selectedTargetDay=new Date().getDay(),libraryTab='base',editingIngredient=null,productPurpose='library',pickerPurpose='diary',scannerStream=null,scannerLoop=0,photoData='',cookingRecipe=null,cookingIndex=0;
let builderIngredients=[],builderSteps=[],builderTimers=[],dragState=null;

function toast(message){const node=$('[data-toast]');node.textContent=message;node.classList.add('is-visible');clearTimeout(node.toastTimer);node.toastTimer=setTimeout(()=>node.classList.remove('is-visible'),3200)}
function setSync(state){$$('[data-sync-dot]').forEach(node=>{node.classList.toggle('is-syncing',state==='syncing');node.classList.toggle('is-error',state==='error')});const label=$('[data-sync-label]');if(label)label.textContent=i18n[locale][state==='syncing'?'syncing':state==='error'?'error':'synced']}
function normalizePayload(value){const base=emptyPayload();const listKeys=['recipes','customCategories','plans','shopping','dailyTargets','weights','vitamins','savedIngredients','trainingDays','diaryEntries'];const result={...base,...(value||{}),goals:{...base.goals,...(value?.goals||{})}};listKeys.forEach(key=>result[key]=Array.isArray(value?.[key])?value[key]:[]);return result}
async function saveData(immediate=false){if(!currentUser)return;if(previewMode){setSync('synced');return}clearTimeout(saveTimer);const run=async()=>{setSync('syncing');try{await setDoc(doc(db,'users',currentUser.uid,'data','main'),{payload:JSON.stringify(payload),schemaVersion:6,updatedAt:serverTimestamp()},{merge:true});setSync('synced')}catch(error){console.error(error);setSync('error');toast(tr('Cloud sync failed. Your current screen remains open.','Cloudsync mislukt. Je huidige scherm blijft open.'))}};if(immediate)await run();else saveTimer=setTimeout(run,500)}
function commit(message){saveData();renderAll();if(message)toast(message)}
function currentTarget(weekday=new Date().getDay()){return {...payload.goals,...(payload.dailyTargets.find(item=>item.weekday===weekday)||{})}}
function totalsForDate(date){return payload.diaryEntries.filter(entry=>entry.date===date).reduce((sum,entry)=>{Object.keys(sum).forEach(key=>sum[key]+=num(entry.macros?.[key]));return sum},emptyMacros())}
function categories(){return [...builtInCategories,...payload.customCategories.map(item=>typeof item==='string'?item:item.name),...payload.recipes.map(item=>item.category)].filter(Boolean).filter((item,index,all)=>all.findIndex(value=>norm(value)===norm(item))===index)}
function baseOverride(base){return payload.savedIngredients.find(item=>norm(item.name)===norm(base.name)||norm(item.nameNl||'')===norm(base.nameNl||''))}
function isBaseSaved(item){return BASE_INGREDIENTS.some(base=>norm(base.name)===norm(item.name)||norm(base.nameNl||'')===norm(item.nameNl||''))}
function allLibraryIngredients(){const base=BASE_INGREDIENTS.map(item=>baseOverride(item)||item);const own=payload.savedIngredients.filter(item=>!isBaseSaved(item));return [...base,...own]}
function matchNutrition(ingredient){if(ingredient.nutritionPer100)return ingredient.nutritionPer100;const saved=payload.savedIngredients.find(item=>(ingredient.barcode&&item.barcode===ingredient.barcode)||norm(item.name)===norm(ingredient.name)||norm(item.nameNl||'')===norm(ingredient.nameNl||''));if(saved)return saved.nutritionPer100;const base=BASE_INGREDIENTS.find(item=>norm(item.name)===norm(ingredient.name)||norm(item.nameNl||'')===norm(ingredient.name)||norm(item.name)===norm(ingredient.nameNl||'')||norm(item.nameNl||'')===norm(ingredient.nameNl||''));return (baseOverride(base||{})||base)?.nutritionPer100}
function gramsFor(item){const amount=num(item.amount);if(['g','ml'].includes(item.unit))return amount;if(['kg','l'].includes(item.unit))return amount*1000;if(item.unit==='dl')return amount*100;if(item.unit==='cl')return amount*10;if(item.unit==='tbsp')return amount*15;if(item.unit==='tsp')return amount*5;if(item.unit==='scoop')return amount*30;return amount*(pieceWeights[norm(item.name)]||100)}
function estimateMacros(ingredients,servings=1){const total=ingredients.reduce((sum,item)=>{const profile=matchNutrition(item);if(!profile)return sum;const factor=gramsFor(item)/100;Object.keys(sum).forEach(key=>sum[key]+=num(profile[key])*factor);return sum},emptyMacros());return Object.fromEntries(Object.entries(total).map(([key,value])=>[key,Math.round(value/Math.max(1,servings))]))}
function productToIngredient(product){const n=product.nutriments||{};const name=product.product_name_nl||product.product_name||product.product_name_en||product.product_name_fr;if(!name)return null;return{id:id('ingredient'),name:String(name),nameNl:product.product_name_nl||undefined,brand:Array.isArray(product.brands)?product.brands.join(', '):product.brands||undefined,barcode:product.code||undefined,imageUrl:product.image_front_small_url||undefined,amount:String(Math.round(num(product.serving_quantity)||100)),unit:'g',nutritionPer100:{calories:num(n['energy-kcal_100g'])||Math.round(num(n.energy_100g)/4.184),protein:num(n.proteins_100g),carbs:num(n.carbohydrates_100g),fat:num(n.fat_100g),fiber:num(n.fiber_100g)},nutritionSource:'open-food-facts'} }
async function lookupBarcode(barcode){const fields='code,product_name,product_name_en,product_name_nl,product_name_fr,brands,image_front_small_url,serving_quantity,nutriments';const response=await fetch(`https://world.openfoodfacts.org/api/v3/product/${encodeURIComponent(barcode)}?cc=be&lc=${locale}&fields=${fields}`);if(!response.ok)throw new Error('network');const data=await response.json();const item=productToIngredient(data.product||{});if(!item)throw new Error('not-found');return item}
async function fetchTimed(url,ms=5000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),ms);try{return await fetch(url,{signal:controller.signal})}finally{clearTimeout(timer)}}
async function searchProducts(term){const fields='code,product_name,product_name_en,product_name_nl,product_name_fr,brands,image_front_small_url,serving_quantity,nutriments,countries_tags';const modern=`https://search.openfoodfacts.org/search?q=${encodeURIComponent(term)}&size=16&fields=${fields}`;const legacy=`https://world.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(term)}&search_simple=1&action=process&json=1&page_size=16&cc=be&lc=${locale}&tagtype_0=countries&tag_contains_0=contains&tag_0=belgium&fields=${fields}`;let data;for(const url of[modern,legacy]){try{const response=await fetchTimed(url);if(!response.ok)continue;data=await response.json();if(data)break}catch{}}if(!data)throw new Error('network');const products=data.hits||data.products||[];return products.map(productToIngredient).filter(item=>item&&item.nutritionPer100.calories>0)}

function applyLocale(){document.documentElement.lang=locale;localStorage.setItem('maugainz-locale',locale);$$('[data-l10n]').forEach(node=>node.textContent=i18n[locale][node.dataset.l10n]||node.textContent);$$('[data-toggle-language]').forEach(node=>node.textContent=locale==='en'?'NL':'EN');const active=$('[data-view].is-active')?.dataset.view||'overview';$('[data-view-title]').textContent=i18n[locale].titles[active];setSync('synced');renderAll()}
function showView(name){$$('[data-view]').forEach(button=>button.classList.toggle('is-active',button.dataset.view===name));$$('[data-view-panel]').forEach(panel=>panel.classList.toggle('is-active',panel.dataset.viewPanel===name));$('[data-view-title]').textContent=i18n[locale].titles[name]||'MauGainZ';$('.sidebar').classList.remove('is-open');if(name==='create'&&!builderIngredients.length)resetBuilder();if(name==='ingredients')renderIngredientLibrary();window.scrollTo({top:0,behavior:'smooth'})}

function entryMarkup(entry,deletable=false){return `<article class="entry"><div class="entry-icon">${entry.source==='recipe'?'R':'P'}</div><div class="entry-main"><b>${esc(locale==='nl'?(entry.nameNl||entry.name):entry.name)}</b><small>${esc(entry.meal)} · ${num(entry.amount)} ${esc(entry.unit)}</small></div><div class="entry-macro"><b>${Math.round(num(entry.macros?.calories))}</b><small>KCAL</small></div>${deletable?`<button class="entry-delete" data-delete-entry="${esc(entry.id)}" aria-label="Delete">×</button>`:''}</article>`}
function renderOverview(){const totals=totalsForDate(localDate()),target=currentTarget();$('[data-today-kcal]').textContent=Math.round(totals.calories).toLocaleString();$('[data-kcal-target]').textContent=` / ${num(target.calories).toLocaleString()} KCAL`;$('[data-kcal-progress]').style.width=`${Math.min(100,target.calories?totals.calories/target.calories*100:0)}%`;$('[data-today-protein]').textContent=`${Math.round(totals.protein)}g`;$('[data-today-carbs]').textContent=`${Math.round(totals.carbs)}g`;$('[data-today-fat]').textContent=`${Math.round(totals.fat)}g`;$('[data-recipe-count]').textContent=payload.recipes.length;const entries=payload.diaryEntries.filter(entry=>entry.date===localDate()).sort((a,b)=>num(b.createdAt)-num(a.createdAt));$('[data-meal-count]').textContent=entries.length;$('[data-training-today]').textContent=payload.trainingDays.find(item=>item.weekday===new Date().getDay())?.label||tr('Rest','Rust');const latest=[...payload.weights].sort((a,b)=>String(b.date).localeCompare(String(a.date)))[0];$('[data-current-weight]').textContent=latest?`${latest.weightKg} kg`:'—';$('[data-recent-entries]').innerHTML=entries.length?entries.slice(0,6).map(entry=>entryMarkup(entry)).join(''):`<div class="empty-state">${tr('No meals logged today.','Vandaag nog geen maaltijden toegevoegd.')}</div>`}
function renderDiary(){const entries=payload.diaryEntries.filter(entry=>entry.date===diaryDate).sort((a,b)=>num(b.createdAt)-num(a.createdAt)),totals=totalsForDate(diaryDate);$('[data-diary-total]').textContent=Math.round(totals.calories).toLocaleString();$('[data-diary-macros]').innerHTML=[['P',totals.protein],['C',totals.carbs],['F',totals.fat],['FIBER',totals.fiber]].map(([label,value])=>`<span><b>${Math.round(value)}g</b><small>${label}</small></span>`).join('');$('[data-diary-entries]').innerHTML=meals.map(meal=>{const items=entries.filter(entry=>entry.meal===meal);return `<section class="meal-group"><h3>${meal.toUpperCase()}</h3>${items.length?items.map(entry=>entryMarkup(entry,true)).join(''):`<div class="empty-state">${tr('Nothing logged.','Niets toegevoegd.')}</div>`}</section>`}).join('');$$('[data-delete-entry]').forEach(button=>button.onclick=()=>{payload.diaryEntries=payload.diaryEntries.filter(entry=>entry.id!==button.dataset.deleteEntry);commit(tr('Diary entry removed.','Dagboekitem verwijderd.'))});const recipeSelect=$('[data-food-form] select[name="recipeId"]');recipeSelect.innerHTML=payload.recipes.length?payload.recipes.map(recipe=>`<option value="${esc(recipe.id)}">${esc(recipeName(recipe))}</option>`).join(''):'<option value="">No recipes</option>'}
function renderRecipes(){const queryText=norm($('[data-recipe-search]')?.value||''),category=$('[data-recipe-category]')?.value||'All',sort=$('[data-recipe-sort]')?.value||'newest';let recipes=payload.recipes.filter(recipe=>(category==='All'||recipe.category===category)&&norm(`${recipe.title} ${recipe.titleNl||''} ${recipe.subtitle||''} ${(recipe.ingredients||[]).map(item=>`${item.name} ${item.nameNl||''}`).join(' ')}`).includes(queryText));recipes.sort((a,b)=>sort==='protein'?num(b.macros?.protein)-num(a.macros?.protein):sort==='calories'?num(b.macros?.calories)-num(a.macros?.calories):num(b.createdAt)-num(a.createdAt));$('[data-recipes]').innerHTML=recipes.length?recipes.map(recipe=>`<article class="recipe-card"><div class="recipe-card-art" ${recipe.photoUri?`style="background-image:linear-gradient(#0004,#0008),url('${esc(recipe.photoUri)}')"`:''}><span>✦</span><button data-favorite-recipe="${esc(recipe.id)}">${recipe.favorite?'♥':'♡'}</button></div><div class="recipe-card-body"><span class="eyebrow">${esc(recipe.category||'RECIPE')}</span><h3>${esc(recipeName(recipe))}</h3><p>${esc(locale==='nl'?(recipe.subtitleNl||recipe.subtitle||''):(recipe.subtitle||''))}</p><div class="recipe-meta"><span>${num(recipe.prepTime)} MIN</span><span>${Math.round(num(recipe.macros?.calories))} KCAL</span><span>${Math.round(num(recipe.macros?.protein))}G P</span></div><div class="card-actions"><button data-open-recipe="${esc(recipe.id)}">OPEN</button><button data-edit-recipe="${esc(recipe.id)}">EDIT</button><button data-delete-recipe="${esc(recipe.id)}">DELETE</button></div></div></article>`).join(''):`<div class="empty-state">${tr('No matching recipes.','Geen overeenkomende recepten.')}</div>`;$$('[data-favorite-recipe]').forEach(button=>button.onclick=()=>{payload.recipes=payload.recipes.map(recipe=>recipe.id===button.dataset.favoriteRecipe?{...recipe,favorite:!recipe.favorite}:recipe);commit()});$$('[data-open-recipe]').forEach(button=>button.onclick=()=>openRecipe(button.dataset.openRecipe));$$('[data-edit-recipe]').forEach(button=>button.onclick=()=>editRecipe(button.dataset.editRecipe));$$('[data-delete-recipe]').forEach(button=>button.onclick=()=>deleteRecipe(button.dataset.deleteRecipe))}

function resetBuilder(){const form=$('[data-recipe-form]');form.reset();form.id.value='';form.prepTime.value='20';form.servings.value='1';builderIngredients=[blankIngredient(),blankIngredient()];builderSteps=['',''];builderTimers=[0,0];photoData='';$('[data-photo-preview]').hidden=true;$('[data-builder-heading]').textContent=tr('Build your fuel','Bouw je brandstof');renderBuilderRows();renderBuilderSelects()}
function blankIngredient(source={}){return{id:source.id||id('ingredient'),name:source.name||'',nameNl:source.nameNl||'',amount:String(source.amount??''),unit:source.unit||'g',brand:source.brand,barcode:source.barcode,imageUrl:source.imageUrl,nutritionPer100:source.nutritionPer100,nutritionSource:source.nutritionSource}}
function renderBuilderSelects(){const options=categories();const select=$('[data-recipe-form] select[name="category"]'),current=select.value;select.innerHTML=options.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('');if(options.includes(current))select.value=current}
function renderBuilderRows(){const ingredientBox=$('[data-ingredient-rows]');ingredientBox.innerHTML=builderIngredients.map((item,index)=>`<div class="ingredient-row" draggable="true" data-kind="ingredient" data-index="${index}"><div class="drag-handle">⠿</div><input data-field="name" value="${esc(item.name)}" placeholder="Ingredient"><input data-field="amount" value="${esc(item.amount)}" inputmode="decimal" placeholder="0"><select data-field="unit">${units.map(unit=>`<option ${unit===item.unit?'selected':''}>${unit}</option>`).join('')}</select><button type="button" class="macro-state" data-review-ingredient="${index}" title="Nutrition">${matchNutrition(item)?'✓':'?'}</button><div class="row-move"><button type="button" data-move-ingredient="-1">↑</button><button type="button" data-move-ingredient="1">↓</button></div><button type="button" class="entry-delete" data-remove-ingredient>×</button></div>`).join('');const stepBox=$('[data-step-rows]');stepBox.innerHTML=builderSteps.map((step,index)=>`<div class="step-row" draggable="true" data-kind="step" data-index="${index}"><div class="drag-handle">⠿</div><b>${String(index+1).padStart(2,'0')}</b><textarea data-step-text placeholder="What happens in this step?">${esc(step)}</textarea><input data-step-timer value="${num(builderTimers[index])||''}" type="number" min="0" placeholder="min"><div class="row-move"><button type="button" data-move-step="-1">↑</button><button type="button" data-move-step="1">↓</button></div><button type="button" class="entry-delete" data-remove-step>×</button></div>`).join('');$('[data-ingredient-count]').textContent=`${builderIngredients.filter(item=>item.name.trim()).length} ${tr('items','items')}`;$('[data-step-count]').textContent=`${builderSteps.filter(Boolean).length} ${tr('steps','stappen')}`;const covered=builderIngredients.filter(item=>item.name.trim()&&matchNutrition(item)).length,total=builderIngredients.filter(item=>item.name.trim()).length;$('[data-macro-coverage]').textContent=`${covered}/${total} ${tr('recognized','herkend')}`;bindBuilderRows()}
function bindBuilderRows(){$$('[data-ingredient-rows] .ingredient-row').forEach((row,index)=>{row.querySelectorAll('[data-field]').forEach(input=>input.oninput=()=>{builderIngredients[index][input.dataset.field]=input.value;renderCoverageOnly()});row.querySelector('[data-review-ingredient]').onclick=()=>editLibraryForBuilder(index);row.querySelector('[data-remove-ingredient]').onclick=()=>{builderIngredients.splice(index,1);renderBuilderRows()};row.querySelectorAll('[data-move-ingredient]').forEach(button=>button.onclick=()=>moveArray(builderIngredients,index,index+num(button.dataset.moveIngredient),renderBuilderRows))});$$('[data-step-rows] .step-row').forEach((row,index)=>{row.querySelector('[data-step-text]').oninput=event=>builderSteps[index]=event.target.value;row.querySelector('[data-step-timer]').oninput=event=>builderTimers[index]=num(event.target.value);row.querySelector('[data-remove-step]').onclick=()=>{builderSteps.splice(index,1);builderTimers.splice(index,1);renderBuilderRows()};row.querySelectorAll('[data-move-step]').forEach(button=>button.onclick=()=>{const to=index+num(button.dataset.moveStep);if(to<0||to>=builderSteps.length)return;[builderSteps[index],builderSteps[to]]=[builderSteps[to],builderSteps[index]];[builderTimers[index],builderTimers[to]]=[builderTimers[to],builderTimers[index]];renderBuilderRows()})});$$('.sortable-list [draggable="true"]').forEach(row=>{row.ondragstart=()=>dragState={kind:row.dataset.kind,index:num(row.dataset.index)};row.ondragover=event=>event.preventDefault();row.ondrop=event=>{event.preventDefault();if(!dragState||dragState.kind!==row.dataset.kind)return;const to=num(row.dataset.index);if(row.dataset.kind==='ingredient')moveArray(builderIngredients,dragState.index,to,renderBuilderRows);else{const [step]=builderSteps.splice(dragState.index,1),[timer]=builderTimers.splice(dragState.index,1);builderSteps.splice(to,0,step);builderTimers.splice(to,0,timer);renderBuilderRows()}dragState=null}})}
function renderCoverageOnly(){const covered=builderIngredients.filter(item=>item.name.trim()&&matchNutrition(item)).length,total=builderIngredients.filter(item=>item.name.trim()).length;$('[data-macro-coverage]').textContent=`${covered}/${total} ${tr('recognized','herkend')}`;$('[data-ingredient-count]').textContent=`${total} items`}
function moveArray(array,from,to,render){if(to<0||to>=array.length)return;const[moved]=array.splice(from,1);array.splice(to,0,moved);render()}
function scaleServings(delta){const input=$('[data-recipe-form] [name="servings"]'),oldValue=Math.max(1,num(input.value)),next=Math.max(1,oldValue+delta),ratio=next/oldValue;builderIngredients=builderIngredients.map(item=>({...item,amount:item.amount&&num(item.amount)?String(round(num(item.amount)*ratio,3)):item.amount}));input.value=next;renderBuilderRows()}
function calculateBuilderMacros(){const values=estimateMacros(builderIngredients,Math.max(1,num($('[data-recipe-form] [name="servings"]').value)));Object.entries(values).forEach(([key,value])=>$(`[data-recipe-form] [name="${key}"]`).value=value);toast(tr('Macros calculated per portion.','Macro’s per portie berekend.'))}
function formRecipe(){const form=$('[data-recipe-form]'),data=new FormData(form);return{id:String(data.get('id')||id('recipe')),title:String(data.get('title')||'').trim(),subtitle:String(data.get('subtitle')||'').trim(),category:String(data.get('category')||'Quick meal'),prepTime:num(data.get('prepTime')),servings:Math.max(1,num(data.get('servings'))),ingredients:builderIngredients.filter(item=>item.name.trim()).map(item=>({...item,amount:String(item.amount||'1')})),steps:builderSteps.map(value=>value.trim()).filter(Boolean),stepTimers:builderSteps.map((value,index)=>value.trim()?num(builderTimers[index]):null).filter(value=>value!==null),macros:{calories:num(data.get('calories')),protein:num(data.get('protein')),carbs:num(data.get('carbs')),fat:num(data.get('fat')),fiber:num(data.get('fiber'))},accent:'#D2A74A',icon:'nutrition-outline',favorite:false,createdAt:Date.now(),photoUri:photoData||undefined,dietaryTags:String(data.get('dietaryTags')||'').split(',').map(value=>value.trim()).filter(Boolean),allergens:String(data.get('allergens')||'').split(',').map(value=>value.trim()).filter(Boolean)}}
function editRecipe(recipeId){const recipe=payload.recipes.find(item=>item.id===recipeId);if(!recipe)return;showView('create');const form=$('[data-recipe-form]');form.id.value=recipe.id;form.title.value=recipe.title;form.subtitle.value=recipe.subtitle||'';renderBuilderSelects();form.category.value=recipe.category||'Quick meal';form.prepTime.value=num(recipe.prepTime);form.servings.value=Math.max(1,num(recipe.servings));form.dietaryTags.value=(recipe.dietaryTags||[]).join(', ');form.allergens.value=(recipe.allergens||[]).join(', ');Object.entries(recipe.macros||{}).forEach(([key,value])=>{if(form[key])form[key].value=value});builderIngredients=(recipe.ingredients||[]).map(blankIngredient);builderSteps=[...(recipe.steps||[])];builderTimers=[...(recipe.stepTimers||builderSteps.map(()=>0))];photoData=recipe.photoUri||'';const preview=$('[data-photo-preview]');preview.hidden=!photoData;preview.style.backgroundImage=photoData?`url('${photoData}')`:'';$('[data-builder-heading]').textContent=tr('Edit recipe','Recept bewerken');renderBuilderRows()}
function deleteRecipe(recipeId){if(!confirm(tr('Delete this recipe? This also removes it from your plan.','Dit recept verwijderen? Het wordt ook uit je planning verwijderd.')))return;payload.recipes=payload.recipes.filter(item=>item.id!==recipeId);payload.plans=payload.plans.filter(item=>item.recipeId!==recipeId);commit(tr('Recipe deleted.','Recept verwijderd.'))}

function openRecipe(recipeId){const recipe=payload.recipes.find(item=>item.id===recipeId);if(!recipe)return;const scaled=1;const detail=$('[data-recipe-detail]');detail.innerHTML=`<div class="recipe-detail-hero" ${recipe.photoUri?`style="background-image:linear-gradient(#0004,#000b),url('${esc(recipe.photoUri)}')"`:''}><div><span class="eyebrow">${esc(recipe.category)}</span><h2>${esc(recipeName(recipe))}</h2></div></div><div class="detail-meta"><span>${num(recipe.prepTime)} MIN</span><span>${num(recipe.servings)} PORTIONS</span><span>${Math.round(num(recipe.macros?.calories))} KCAL</span><span>${Math.round(num(recipe.macros?.protein))}G PROTEIN</span></div><div class="detail-columns"><section><h3>Ingredients</h3><ul class="detail-list">${(recipe.ingredients||[]).map(item=>`<li><b>${esc(item.amount)} ${esc(item.unit)}</b> ${esc(ingredientName(item))}</li>`).join('')}</ul></section><section><h3>Preparation</h3><ol class="detail-list">${(locale==='nl'&&recipe.stepsNl?.length?recipe.stepsNl:recipe.steps||[]).map((step,index)=>`<li>${esc(step)}${num(recipe.stepTimers?.[index])?` <b>(${num(recipe.stepTimers[index])} min)</b>`:''}</li>`).join('')}</ol></section></div><div class="detail-actions"><button class="primary-button" data-detail-cook>START COOKING</button><button class="outline-button" data-detail-diary>ADD TO DIARY</button><button class="outline-button" data-detail-shopping>ADD TO SHOPPING</button><button class="outline-button" data-detail-duplicate>DUPLICATE</button><button class="outline-button" data-detail-edit>EDIT</button></div>`;$('[data-detail-cook]').onclick=()=>startCooking(recipe);$('[data-detail-diary]').onclick=()=>{addRecipeToDiary(recipe,diaryDate,'Dinner',1);$('[data-recipe-dialog]').close()};$('[data-detail-shopping]').onclick=()=>{addRecipeShopping(recipe);$('[data-recipe-dialog]').close()};$('[data-detail-duplicate]').onclick=()=>{const copy={...recipe,id:id('recipe'),title:`${recipe.title} ${tr('copy','kopie')}`,favorite:false,createdAt:Date.now(),ingredients:recipe.ingredients.map(blankIngredient)};payload.recipes.unshift(copy);commit(tr('Recipe duplicated.','Recept gedupliceerd.'));$('[data-recipe-dialog]').close()};$('[data-detail-edit]').onclick=()=>{$('[data-recipe-dialog]').close();editRecipe(recipe.id)};$('[data-recipe-dialog]').showModal()}
function startCooking(recipe){cookingRecipe=recipe;cookingIndex=0;$('[data-recipe-dialog]').close();renderCooking();$('[data-cooking-dialog]').showModal()}
function renderCooking(){if(!cookingRecipe)return;const steps=locale==='nl'&&cookingRecipe.stepsNl?.length?cookingRecipe.stepsNl:cookingRecipe.steps||[],step=steps[cookingIndex]||tr('No preparation steps.','Geen bereidingsstappen.');$('[data-cooking-mode]').innerHTML=`<div class="cooking-card"><span class="eyebrow">${esc(recipeName(cookingRecipe))}</span><h2>${tr('Step','Stap')} ${Math.min(cookingIndex+1,steps.length)} / ${steps.length}</h2><div class="cooking-step">${esc(step)}</div>${num(cookingRecipe.stepTimers?.[cookingIndex])?`<p>${num(cookingRecipe.stepTimers[cookingIndex])} MIN TIMER</p>`:''}<div class="cooking-nav"><button class="outline-button" data-cook-prev ${cookingIndex===0?'disabled':''}>← PREVIOUS</button><button class="primary-button" data-cook-next>${cookingIndex>=steps.length-1?'FINISH':'NEXT →'}</button></div></div>`;$('[data-cook-prev]').onclick=()=>{cookingIndex=Math.max(0,cookingIndex-1);renderCooking()};$('[data-cook-next]').onclick=()=>{if(cookingIndex>=steps.length-1){$('[data-cooking-dialog]').close();return}cookingIndex++;renderCooking()}}
function addRecipeToDiary(recipe,date,meal,amount){const factor=Math.max(.1,num(amount));payload.diaryEntries.unshift({id:id('diary'),date,meal,source:'recipe',name:recipe.title,nameNl:recipe.titleNl,amount:factor,unit:'portion',macros:Object.fromEntries(Object.entries(recipe.macros||emptyMacros()).map(([key,value])=>[key,round(num(value)*factor)])),createdAt:Date.now(),recipeId:recipe.id});commit(tr('Recipe added to diary.','Recept toegevoegd aan dagboek.'))}
function addRecipeShopping(recipe){payload.shopping.push(...(recipe.ingredients||[]).map(item=>({id:id('shop'),name:ingredientName(item),amount:item.amount,unit:item.unit,checked:false,recipeId:recipe.id})));commit(tr('Ingredients added to shopping list.','Ingrediënten toegevoegd aan boodschappenlijst.'))}

function renderPlan(){const recipeOptions=payload.recipes.map(recipe=>`<option value="${esc(recipe.id)}">${esc(recipeName(recipe))}</option>`).join('');$('[data-plan-form] select[name="recipeId"]').innerHTML=recipeOptions||'<option value="">No recipes</option>';$('[data-plans]').innerHTML=[...payload.plans].sort((a,b)=>String(a.date).localeCompare(String(b.date))).map(item=>{const recipe=payload.recipes.find(entry=>entry.id===item.recipeId);return `<div class="plan-item"><div><b>${esc(recipe?recipeName(recipe):'Recipe')}</b><small>${esc(item.date)} · ${esc(item.meal)}${item.tag?` · ${esc(item.tag)}`:''}</small></div><span>${Math.round(num(recipe?.macros?.calories))} KCAL</span><button class="entry-delete" data-remove-plan="${esc(item.id)}">×</button></div>`}).join('')||'<div class="empty-state">Your meal plan is empty.</div>';const days=dayNames();$('[data-training-editor]').innerHTML=days.map((day,index)=>{const weekday=index===6?0:index+1,training=payload.trainingDays.find(item=>item.weekday===weekday);return `<div class="training-row"><label>${esc(day)} </label><input data-training-day="${weekday}" value="${esc(training?.label||'')}" placeholder="${tr('Rest / Push / Pull / Legs','Rust / Push / Pull / Legs')}"></div>`}).join('');$('[data-shopping]').innerHTML=payload.shopping.map(item=>`<div class="shopping-row ${item.checked?'is-checked':''}"><button class="shopping-check" data-toggle-shopping="${esc(item.id)}">${item.checked?'✓':''}</button><div><b>${esc(item.name)}</b><small>${esc(item.amount||'')} ${esc(item.unit||'')}</small></div><button class="entry-delete" data-remove-shopping="${esc(item.id)}">×</button></div>`).join('')||'<div class="empty-state">Your shopping list is empty.</div>';$$('[data-remove-plan]').forEach(button=>button.onclick=()=>{payload.plans=payload.plans.filter(item=>item.id!==button.dataset.removePlan);commit()});$$('[data-training-day]').forEach(input=>input.onchange=()=>{payload.trainingDays=payload.trainingDays.filter(item=>item.weekday!==num(input.dataset.trainingDay));if(input.value.trim())payload.trainingDays.push({weekday:num(input.dataset.trainingDay),label:input.value.trim()});commit(tr('Training split saved.','Trainingsschema opgeslagen.'))});$$('[data-toggle-shopping]').forEach(button=>button.onclick=()=>{payload.shopping=payload.shopping.map(item=>item.id===button.dataset.toggleShopping?{...item,checked:!item.checked}:item);commit()});$$('[data-remove-shopping]').forEach(button=>button.onclick=()=>{payload.shopping=payload.shopping.filter(item=>item.id!==button.dataset.removeShopping);commit()})}
function dayNames(){const base=new Date(2024,0,8);return Array.from({length:7},(_,index)=>new Date(base.getTime()+index*86400000).toLocaleDateString(locale==='nl'?'nl-BE':'en-GB',{weekday:'long'}))}
function renderPerformance(){const days=dayNames();$('[data-target-days]').innerHTML=days.map((day,index)=>{const weekday=index===6?0:index+1,target=currentTarget(weekday);return `<button class="day-button ${selectedTargetDay===weekday?'is-active':''}" data-target-day="${weekday}"><span>${esc(day.slice(0,3).toUpperCase())}</span><b>${Math.round(num(target.calories))}</b></button>`}).join('');const target=currentTarget(selectedTargetDay),form=$('[data-target-form]');['calories','protein','carbs','fat'].forEach(key=>form[key].value=num(target[key]));$('[data-target-day-title]').textContent=days[selectedTargetDay===0?6:selectedTargetDay-1];const planned=payload.plans.filter(item=>new Date(`${item.date}T12:00:00`).getDay()===selectedTargetDay).map(item=>payload.recipes.find(recipe=>recipe.id===item.recipeId)).filter(Boolean).reduce((sum,recipe)=>{Object.keys(sum).forEach(key=>sum[key]+=num(recipe.macros?.[key]));return sum},emptyMacros());$('[data-planned-progress]').innerHTML=`<b>${Math.round(planned.calories)} / ${Math.round(num(target.calories))} kcal ${tr('planned','gepland')}</b><div class="bar"><i style="width:${Math.min(100,target.calories?planned.calories/target.calories*100:0)}%"></i></div><small>P ${Math.round(planned.protein)} · C ${Math.round(planned.carbs)} · F ${Math.round(planned.fat)}</small>`;const weights=[...payload.weights].sort((a,b)=>String(b.date).localeCompare(String(a.date)));$('[data-weight-list]').innerHTML=weights.slice(0,10).map((item,index)=>`<div class="history-row"><div><b>${item.weightKg} kg</b><small>${esc(item.date)}${weights[index+1]?` · ${round(item.weightKg-weights[index+1].weightKg)>0?'+':''}${round(item.weightKg-weights[index+1].weightKg)} kg`:''}</small></div><button class="entry-delete" data-remove-weight="${esc(item.id)}">×</button></div>`).join('')||'<div class="empty-state">No weight entries yet.</div>';const graph=[...weights].slice(0,12).reverse(),values=graph.map(item=>num(item.weightKg)),min=Math.min(...values,0),max=Math.max(...values,1);$('[data-weight-chart]').innerHTML=graph.map(item=>`<div class="weight-bar" style="height:${25+((num(item.weightKg)-min)/(max-min||1))*65}%"><span>${item.weightKg}</span></div>`).join('');$('[data-vitamins]').innerHTML=payload.vitamins.map(item=>{const taken=(item.takenDates||[]).includes(localDate());return `<div class="vitamin-row"><div><b>${esc(item.name)}</b><small>${esc(item.dose||'')}</small></div><button class="taken-button ${taken?'is-taken':''}" data-toggle-vitamin="${esc(item.id)}">${taken?'TAKEN ✓':'TAKE'}</button><button class="entry-delete" data-remove-vitamin="${esc(item.id)}">×</button></div>`}).join('')||'<div class="empty-state">Add your daily vitamins.</div>';$$('[data-target-day]').forEach(button=>button.onclick=()=>{selectedTargetDay=num(button.dataset.targetDay);renderPerformance()});$$('[data-remove-weight]').forEach(button=>button.onclick=()=>{payload.weights=payload.weights.filter(item=>item.id!==button.dataset.removeWeight);commit()});$$('[data-toggle-vitamin]').forEach(button=>button.onclick=()=>{payload.vitamins=payload.vitamins.map(item=>{if(item.id!==button.dataset.toggleVitamin)return item;const dates=item.takenDates||[],taken=dates.includes(localDate());return{...item,takenDates:taken?dates.filter(date=>date!==localDate()):[...dates,localDate()]}});commit()});$$('[data-remove-vitamin]').forEach(button=>button.onclick=()=>{payload.vitamins=payload.vitamins.filter(item=>item.id!==button.dataset.removeVitamin);commit()})}

function renderIngredientLibrary(){const queryText=norm($('[data-ingredient-search]')?.value||''),baseItems=BASE_INGREDIENTS.map(base=>({...base,...(baseOverride(base)||{}),_base:base})),mine=payload.savedIngredients.filter(item=>!isBaseSaved(item));$('[data-base-count]').textContent=BASE_INGREDIENTS.length;$('[data-mine-count]').textContent=mine.length;$$('[data-library-tab]').forEach(button=>button.classList.toggle('is-active',button.dataset.libraryTab===libraryTab));const items=(libraryTab==='base'?baseItems:mine).filter(item=>norm(`${item.name} ${item.nameNl||''} ${item.brand||''} ${item.group||''}`).includes(queryText));$('[data-ingredient-library]').innerHTML=items.length?items.map((item,index)=>`<div class="ingredient-library-row"><button data-edit-library="${index}"><b>${esc(ingredientName(item))}</b><small>${esc(item.brand?`${item.brand} · `:'')}${num(item.nutritionPer100?.calories)} kcal / 100 ${esc(item.baseUnit||'g')}</small><em>P ${num(item.nutritionPer100?.protein)} · C ${num(item.nutritionPer100?.carbs)} · F ${num(item.nutritionPer100?.fat)} · ${tr('fiber','vezel')} ${num(item.nutritionPer100?.fiber)}</em></button>${item._base&&baseOverride(item._base)?'<span class="eyebrow">CHANGED</span>':''}</div>`).join(''):'<div class="empty-state">No ingredients found.</div>';$$('[data-edit-library]').forEach(button=>button.onclick=()=>{editingIngredient=items[num(button.dataset.editLibrary)];renderIngredientEditor()});if(editingIngredient)renderIngredientEditor()}
function renderIngredientEditor(){const item=editingIngredient||{id:'',name:'',nameNl:'',brand:'',barcode:'',baseUnit:'g',servingSize:100,nutritionPer100:emptyMacros()},base=item._base;const values={...item,nutritionPer100:{...emptyMacros(),...(item.nutritionPer100||{})}};$('[data-ingredient-editor]').innerHTML=`<span class="eyebrow">${base?'MAUGAINZ BASE OVERRIDE':'MY INGREDIENT'}</span><h3>${base?esc(ingredientName(base)):values.id?tr('Edit ingredient','Ingrediënt bewerken'):tr('Add custom ingredient','Eigen ingrediënt toevoegen')}</h3><form data-ingredient-editor-form><label>Name<input name="name" value="${esc(base?base.name:values.name)}" ${base?'readonly':''}></label><label>Dutch name<input name="nameNl" value="${esc(base?base.nameNl||'':values.nameNl||'')}" ${base?'readonly':''}></label><div class="form-grid"><label>Brand<input name="brand" value="${esc(values.brand||'')}"></label><label>Barcode / EAN<input name="barcode" value="${esc(values.barcode||'')}" inputmode="numeric"></label></div><div class="form-grid"><label>Base unit<select name="baseUnit"><option ${values.baseUnit==='g'?'selected':''}>g</option><option ${values.baseUnit==='ml'?'selected':''}>ml</option></select></label><label>Quick-add amount<input name="servingSize" type="number" value="${num(values.servingSize)||100}"></label></div><label>NUTRITION PER 100 G / ML</label><div class="macro-fields">${[['calories','KCAL'],['protein','P'],['carbs','C'],['fat','F'],['fiber','FIBER']].map(([key,label])=>`<label>${label}<input name="${key}" type="number" step="0.1" value="${num(values.nutritionPer100[key])}"></label>`).join('')}</div><div class="button-row"><button class="primary-button">SAVE NUTRITION</button>${values.id&&!base?'<button type="button" class="danger-button" data-delete-ingredient>DELETE</button>':''}${base&&baseOverride(base)?'<button type="button" class="outline-button" data-reset-base>RESET DEFAULT</button>':''}</div></form>`;const form=$('[data-ingredient-editor-form]');form.onsubmit=event=>{event.preventDefault();const data=new FormData(form);if(!String(data.get('name')).trim())return;const saved={id:base?(baseOverride(base)?.id||id('override')):(values.id||id('saved')),name:base?base.name:String(data.get('name')).trim(),nameNl:base?base.nameNl:String(data.get('nameNl')||'').trim()||undefined,brand:String(data.get('brand')||'').trim()||undefined,barcode:String(data.get('barcode')||'').trim()||undefined,baseUnit:String(data.get('baseUnit')),servingSize:num(data.get('servingSize'))||100,nutritionPer100:{calories:num(data.get('calories')),protein:num(data.get('protein')),carbs:num(data.get('carbs')),fat:num(data.get('fat')),fiber:num(data.get('fiber'))}};payload.savedIngredients=[saved,...payload.savedIngredients.filter(entry=>entry.id!==saved.id&&!(base&&(norm(entry.name)===norm(base.name)||norm(entry.nameNl||'')===norm(base.nameNl||''))))];editingIngredient=base?{...saved,_base:base}:saved;commit(tr('Ingredient nutrition saved.','Voedingswaarden opgeslagen.'))};$('[data-delete-ingredient]')?.addEventListener('click',()=>{payload.savedIngredients=payload.savedIngredients.filter(entry=>entry.id!==values.id);editingIngredient=null;commit(tr('Ingredient deleted.','Ingrediënt verwijderd.'));$('[data-ingredient-editor]').innerHTML='<div class="empty-state">Choose an ingredient or add your own product.</div>'});$('[data-reset-base]')?.addEventListener('click',()=>{const override=baseOverride(base);payload.savedIngredients=payload.savedIngredients.filter(entry=>entry.id!==override?.id);editingIngredient={...base,_base:base};commit(tr('Base values restored.','Standaardwaarden hersteld.'))})}
function editLibraryForBuilder(index){const item=builderIngredients[index],existing=allLibraryIngredients().find(value=>(item.barcode&&value.barcode===item.barcode)||norm(value.name)===norm(item.name)||norm(value.nameNl||'')===norm(item.nameNl||''));editingIngredient=existing||{...item,id:'',baseUnit:['ml'].includes(item.unit)?'ml':'g',servingSize:num(item.amount)||100,nutritionPer100:matchNutrition(item)||emptyMacros()};showView('ingredients');renderIngredientEditor();toast(tr('Confirm the ingredient values, then return to your recipe.','Bevestig de waarden en ga daarna terug naar je recept.'))}

function renderFriends(){if(!currentUser)return;const incoming=connections.filter(item=>item.toUid===currentUser.uid&&item.status==='pending');const accepted=connections.filter(item=>item.status==='accepted').map(item=>item.fromUid===currentUser.uid?{uid:item.toUid,name:item.toName,code:item.toCode}:{uid:item.fromUid,name:item.fromName,code:item.fromCode});$('[data-friend-requests]').innerHTML=incoming.length?incoming.map(item=>`<div class="friend-row"><div class="avatar">${esc(item.fromName?.slice(0,1).toUpperCase()||'?')}</div><div><b>${esc(item.fromName)}</b><small>${esc(item.fromCode)}</small></div><button class="row-action" data-accept-friend="${esc(item.id)}">ACCEPT</button></div>`).join(''):'<div class="empty-state">No new requests.</div>';$('[data-friends]').innerHTML=accepted.length?accepted.map(item=>`<div class="friend-row"><div class="avatar">${esc(item.name?.slice(0,1).toUpperCase()||'?')}</div><div><b>${esc(item.name)}</b><small>${esc(item.code)}</small></div><span class="eyebrow">FRIEND</span></div>`).join(''):'<div class="empty-state">No friends yet.</div>';$('[data-share-form] select[name="friend"]').innerHTML=`<option value="">Choose a friend</option>${accepted.map(item=>`<option value="${esc(item.uid)}">${esc(item.name)}</option>`).join('')}`;$('[data-share-form] select[name="recipe"]').innerHTML=`<option value="">Choose a recipe</option>${payload.recipes.map(recipe=>`<option value="${esc(recipe.id)}">${esc(recipeName(recipe))}</option>`).join('')}`;const pending=shares.filter(item=>item.status==='pending');$('[data-shared-recipes]').innerHTML=pending.length?pending.map(item=>{let recipe={};try{recipe=JSON.parse(item.recipeJson)}catch{}return `<div class="share-row"><div><b>${esc(recipe.title||'Shared recipe')}</b><small>From ${esc(item.fromName)}</small></div><button class="row-action" data-accept-share="${esc(item.id)}">ADD</button></div>`}).join(''):'<div class="empty-state">Recipes shared with you appear here.</div>';$$('[data-accept-friend]').forEach(button=>button.onclick=async()=>{await updateDoc(doc(db,'friendRequests',button.dataset.acceptFriend),{status:'accepted',acceptedAt:serverTimestamp()});toast(tr('Friend added.','Vriend toegevoegd.'))});$$('[data-accept-share]').forEach(button=>button.onclick=async()=>{const item=shares.find(entry=>entry.id===button.dataset.acceptShare);if(!item)return;const recipe=JSON.parse(item.recipeJson);payload.recipes.unshift({...recipe,id:id('shared'),favorite:false,createdAt:Date.now()});await Promise.all([saveData(true),updateDoc(doc(db,'recipeShares',item.id),{status:'accepted',acceptedAt:serverTimestamp()})]);toast(tr('Recipe added to your cookbook.','Recept toegevoegd aan je kookboek.'));renderAll()})}
function renderSettings(){const form=$('[data-goals-form]');Object.entries(payload.goals).forEach(([key,value])=>{if(form[key])form[key].value=value});$('[data-unit-system]').value=payload.unitSystem||'metric';$('[data-categories]').innerHTML=payload.customCategories.map((item,index)=>{const name=typeof item==='string'?item:item.name;return `<div class="category-row"><b>${esc(name)}</b><button class="entry-delete" data-remove-category="${index}">×</button></div>`}).join('')||'<div class="empty-state">No custom categories.</div>';$$('[data-remove-category]').forEach(button=>button.onclick=()=>{const removed=payload.customCategories.splice(num(button.dataset.removeCategory),1)[0],name=typeof removed==='string'?removed:removed?.name;payload.recipes=payload.recipes.map(recipe=>recipe.category===name?{...recipe,category:'Quick meal'}:recipe);commit();renderBuilderSelects()})}
function renderAll(){renderOverview();renderDiary();renderRecipes();renderPlan();renderPerformance();renderIngredientLibrary();renderFriends();renderSettings();renderSelects()}
function renderSelects(){const categorySelect=$('[data-recipe-category]'),current=categorySelect.value||'All';categorySelect.innerHTML=`<option>All</option>${categories().map(value=>`<option>${esc(value)}</option>`).join('')}`;categorySelect.value=[...categorySelect.options].some(option=>option.value===current)?current:'All';renderBuilderSelects()}

async function ensureProfile(user){const profileRef=doc(db,'publicProfiles',user.uid),snapshot=await getDoc(profileRef),displayName=user.displayName||user.email?.split('@')[0]||'Athlete',code=friendCodeFor(user.uid);if(!snapshot.exists())await setDoc(profileRef,{uid:user.uid,displayName,friendCode:code,createdAt:serverTimestamp()});await setDoc(doc(db,'friendCodes',code),{uid:user.uid,displayName,updatedAt:serverTimestamp()},{merge:true});return{displayName,friendCode:code,...(snapshot.exists()?snapshot.data():{})}}
function subscribeFriends(user){unsubscribeFriends.forEach(unsubscribe=>unsubscribe());let incoming=[],outgoing=[];const combine=()=>{connections=[...incoming,...outgoing];renderFriends()};unsubscribeFriends=[onSnapshot(query(collection(db,'friendRequests'),where('toUid','==',user.uid)),snapshot=>{incoming=snapshot.docs.map(item=>({id:item.id,...item.data()}));combine()}),onSnapshot(query(collection(db,'friendRequests'),where('fromUid','==',user.uid)),snapshot=>{outgoing=snapshot.docs.map(item=>({id:item.id,...item.data()}));combine()}),onSnapshot(query(collection(db,'recipeShares'),where('toUid','==',user.uid)),snapshot=>{shares=snapshot.docs.map(item=>({id:item.id,...item.data()})).sort((a,b)=>(b.createdAt?.toMillis?.()||0)-(a.createdAt?.toMillis?.()||0));renderFriends()})]}
function openDashboard(user,profile){currentUser=user;$('[data-auth]').hidden=true;$('[data-dashboard]').hidden=false;const name=profile.displayName||user.displayName||user.email.split('@')[0];$$('[data-user-name],[data-settings-name]').forEach(node=>node.textContent=name);$$('[data-user-email],[data-settings-email]').forEach(node=>node.textContent=user.email);$$('[data-avatar],[data-settings-avatar]').forEach(node=>node.textContent=name.slice(0,1).toUpperCase());$('[data-friend-code]').textContent=profile.friendCode||friendCodeFor(user.uid);unsubscribeData?.();unsubscribeData=onSnapshot(doc(db,'users',user.uid,'data','main'),async snapshot=>{if(!snapshot.exists()){payload=emptyPayload();await saveData(true)}else{try{payload=normalizePayload(JSON.parse(snapshot.data().payload||'{}'));setSync('synced')}catch{payload=emptyPayload();setSync('error')}}renderAll()},()=>setSync('error'));subscribeFriends(user);resetBuilder();$('[data-diary-date]').value=diaryDate;$('[data-plan-form] [name="date"]').value=diaryDate;$('[data-weight-form] [name="date"]').value=diaryDate;applyLocale()}
function openAuth(){currentUser=null;unsubscribeData?.();unsubscribeFriends.forEach(unsubscribe=>unsubscribe());$('[data-dashboard]').hidden=true;$('[data-auth]').hidden=false}
function setAuthMode(mode){authMode=mode;$$('[data-auth-mode]').forEach(button=>button.classList.toggle('is-active',button.dataset.authMode===mode));$('[data-name-field]').hidden=mode!=='signup';$('[data-auth-submit]').firstChild.textContent=mode==='signup'?'CREATE ACCOUNT ':'SIGN IN ';$('[data-reset-password]').hidden=mode!=='login';$('[data-auth-form] [name="password"]').autocomplete=mode==='signup'?'new-password':'current-password'}

async function useProduct(item){const saved={id:id('saved'),name:item.name,nameNl:item.nameNl,brand:item.brand,barcode:item.barcode,baseUnit:item.unit==='ml'?'ml':'g',servingSize:num(item.amount)||100,nutritionPer100:item.nutritionPer100};const existing=payload.savedIngredients.find(value=>(saved.barcode&&value.barcode===saved.barcode)||norm(value.name)===norm(saved.name));if(!existing)payload.savedIngredients.unshift(saved);if(productPurpose==='builder'){const blank=builderIngredients.findIndex(value=>!value.name.trim());if(blank>=0)builderIngredients[blank]=blankIngredient(item);else builderIngredients.push(blankIngredient(item));renderBuilderRows();showView('create')}else if(productPurpose==='diary'){fillDiaryProduct(item);showView('diary')}else{editingIngredient=existing||saved;libraryTab='mine';showView('ingredients');renderIngredientEditor()}$('[data-product-dialog]').close();saveData();toast(tr('Product selected—confirm the nutrition if needed.','Product gekozen—bevestig indien nodig de voedingswaarden.'))}
function fillDiaryProduct(item){const form=$('[data-food-form]');diaryMode='product';setDiaryMode();form.name.value=ingredientName(item);form.amount.value=num(item.amount)||100;form.unit.value=item.unit==='ml'?'ml':'g';const factor=num(form.amount.value)/100;Object.entries(item.nutritionPer100||emptyMacros()).forEach(([key,value])=>{if(form[key])form[key].value=round(num(value)*factor)})}
function setDiaryMode(){$$('[data-diary-mode]').forEach(button=>button.classList.toggle('is-active',button.dataset.diaryMode===diaryMode));$('[data-product-fields]').hidden=diaryMode!=='product';$('[data-product-macros]').hidden=diaryMode!=='product';$('[data-recipe-field]').hidden=diaryMode!=='recipe'}
function openProductSearch(purpose='library'){productPurpose=purpose;$('[data-product-results]').innerHTML='';$('[data-product-status]').textContent='';$('[data-product-dialog]').showModal()}
function renderProductResults(items){$('[data-product-results]').innerHTML=items.length?items.map((item,index)=>`<div class="product-row">${item.imageUrl?`<img src="${esc(item.imageUrl)}" alt="">`:'<div class="entry-icon">P</div>'}<div><b>${esc(ingredientName(item))}</b><small>${esc(item.brand||'')} · ${Math.round(num(item.nutritionPer100.calories))} kcal / 100g</small><small>P ${round(item.nutritionPer100.protein)} · C ${round(item.nutritionPer100.carbs)} · F ${round(item.nutritionPer100.fat)}</small></div><button class="small-button" data-use-product="${index}">USE</button></div>`).join(''):'<div class="empty-state">No Belgian products found.</div>';$$('[data-use-product]').forEach(button=>button.onclick=()=>useProduct(items[num(button.dataset.useProduct)]))}
function openLibraryPicker(purpose){pickerPurpose=purpose;renderPicker();$('[data-library-picker]').showModal()}
function renderPicker(){const queryText=norm($('[data-picker-search]').value),items=allLibraryIngredients().filter(item=>norm(`${item.name} ${item.nameNl||''} ${item.brand||''}`).includes(queryText)).slice(0,100);$('[data-picker-results]').innerHTML=items.map((item,index)=>`<div class="product-row"><div class="entry-icon">I</div><div><b>${esc(ingredientName(item))}</b><small>${num(item.nutritionPer100?.calories)} kcal / 100 ${esc(item.baseUnit||'g')}</small></div><button class="small-button" data-pick-library="${index}">USE</button></div>`).join('');$$('[data-pick-library]').forEach(button=>button.onclick=()=>{const item=items[num(button.dataset.pickLibrary)],ingredient=blankIngredient({...item,amount:String(item.servingSize||100),unit:item.baseUnit||'g',nutritionSource:'maugainz'});if(pickerPurpose==='builder'){const blank=builderIngredients.findIndex(value=>!value.name.trim());if(blank>=0)builderIngredients[blank]=ingredient;else builderIngredients.push(ingredient);renderBuilderRows()}else fillDiaryProduct(ingredient);$('[data-library-picker]').close()})}
async function openScanner(purpose){productPurpose=purpose;$('[data-scanner-status]').textContent=tr('Starting camera…','Camera starten…');$('[data-scanner-dialog]').showModal();if(!('BarcodeDetector'in window)){ $('[data-scanner-status]').textContent=tr('Automatic scanning is not supported here. Enter the EAN below.','Automatisch scannen wordt hier niet ondersteund. Vul de EAN hieronder in.');return}try{scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});const video=$('[data-scanner-video]');video.srcObject=scannerStream;await video.play();const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e']});const scan=async()=>{if(!scannerStream)return;try{const codes=await detector.detect(video);if(codes[0]?.rawValue){await processBarcode(codes[0].rawValue);return}}catch{}scannerLoop=requestAnimationFrame(scan)};scan()}catch{$('[data-scanner-status]').textContent=tr('Camera unavailable. Enter the barcode manually.','Camera niet beschikbaar. Vul de barcode handmatig in.')}}
function closeScanner(){cancelAnimationFrame(scannerLoop);scannerStream?.getTracks().forEach(track=>track.stop());scannerStream=null;$('[data-scanner-dialog]').close()}
async function processBarcode(code){$('[data-scanner-status]').textContent=tr('Looking up product…','Product opzoeken…');try{const item=await lookupBarcode(code);closeScanner();await useProduct(item)}catch{$('[data-scanner-status]').textContent=tr('Product not found. You can add it manually in the ingredient library.','Product niet gevonden. Voeg het handmatig toe in de ingrediëntenbibliotheek.')}}

const ingredientPattern=/^[-•*]?\s*(\d+(?:[.,/]\d+)?(?:\s+\d+\/\d+)?)?\s*(kg|mg|g|gram|ml|cl|dl|l|liter|tbsp|tsp|el|eetlepel|tl|theelepel|cup|cups|scoop|scoops|stuk|stuks|piece|pieces|x)?\s+(.+)$/i;
function parseAmount(raw=''){if(!raw.includes('/'))return raw.replace(',','.')||'1';return String(raw.trim().split(/\s+/).reduce((total,part)=>{if(!part.includes('/'))return total+num(part);const[a,b]=part.split('/').map(Number);return total+(b?a/b:0)},0))}
function normalizeUnit(raw=''){const value=raw.toLowerCase();if(/^(g|gram)$/.test(value))return'g';if(/^(l|liter)$/.test(value))return'l';if(/^(el|eetlepel|tbsp)$/.test(value))return'tbsp';if(/^(tl|theelepel|tsp)$/.test(value))return'tsp';if(/^(scoops?|schep)$/.test(value))return'scoop';if(/^(stuks?|pieces?|x)$/.test(value))return'pc';return value||'pc'}
function parseRecipeText(raw){const lines=raw.split(/\r?\n/).map(line=>line.trim()).filter(Boolean),title=lines[0]?.replace(/^#+\s*/,'')||'Imported recipe';let section='unknown',servings,prepTime;const ingredients=[],steps=[];for(const original of lines.slice(1)){const line=original.replace(/^#+\s*/,'').trim();if(/^(ingredients?|ingredienten|benodigdheden)\b/i.test(line)){section='ingredients';continue}if(/^(instructions?|directions?|method|preparation|bereiding|stappen|instructies)\b/i.test(line)){section='steps';continue}const serving=line.match(/(?:servings?|porties?|personen)\D*(\d+)/i);if(serving){servings=num(serving[1]);continue}const time=line.match(/(?:prep(?:aration)?\s*time|bereidingstijd)\D*(\d+)/i);if(time){prepTime=num(time[1]);continue}const match=line.match(ingredientPattern),numbered=/^\d+[.)]\s/.test(line);if((section==='ingredients'||(match&&!numbered))&&match){ingredients.push(blankIngredient({name:match[3].trim(),amount:parseAmount(match[1]||''),unit:normalizeUnit(match[2]||'')}))}else if(section==='steps'||numbered)steps.push(line.replace(/^\d+[.)]\s*/,'').trim())}return{title,ingredients,steps,servings,prepTime}}
function cleanHtml(value=''){const docu=new DOMParser().parseFromString(String(value),'text/html');return(docu.body.textContent||'').replace(/\s+/g,' ').trim()}
function extractJsonLd(html,url){const docu=new DOMParser().parseFromString(html,'text/html'),scripts=[...docu.querySelectorAll('script[type="application/ld+json"]')];for(const script of scripts){try{const parsed=JSON.parse(script.textContent),roots=Array.isArray(parsed)?parsed:[parsed],nodes=roots.flatMap(root=>root?.['@graph']||[root]),recipe=nodes.find(node=>(Array.isArray(node?.['@type'])?node['@type']:[node?.['@type']]).includes('Recipe'));if(!recipe)continue;const ingredients=(Array.isArray(recipe.recipeIngredient)?recipe.recipeIngredient:[recipe.recipeIngredient]).filter(Boolean).map(line=>{const text=cleanHtml(line),match=text.match(ingredientPattern);return blankIngredient({name:(match?.[3]||text).trim(),amount:parseAmount(match?.[1]||''),unit:normalizeUnit(match?.[2]||'')})});const flatten=value=>(Array.isArray(value)?value:[value]).flatMap(step=>typeof step==='string'?[step]:step?.itemListElement?flatten(step.itemListElement):[step?.text||step?.name]).map(cleanHtml).filter(Boolean);const duration=String(recipe.prepTime||recipe.totalTime||'').match(/PT(?:(\d+)H)?(?:(\d+)M)?/i);return{title:cleanHtml(recipe.name)||'Imported recipe',subtitle:cleanHtml(recipe.description),servings:num(String(recipe.recipeYield||'').match(/\d+/)?.[0])||undefined,prepTime:duration?num(duration[1])*60+num(duration[2]):undefined,ingredients,steps:flatten(recipe.recipeInstructions),photoUri:Array.isArray(recipe.image)?recipe.image[0]:typeof recipe.image==='object'?recipe.image?.url:recipe.image,sourceUrl:url}}catch{}}return null}
function applyImportedRecipe(recipe){resetBuilder();const form=$('[data-recipe-form]');form.title.value=recipe.title||'';form.subtitle.value=recipe.subtitle||'';if(recipe.servings)form.servings.value=recipe.servings;if(recipe.prepTime)form.prepTime.value=recipe.prepTime;builderIngredients=recipe.ingredients?.length?recipe.ingredients:[blankIngredient()];builderSteps=recipe.steps?.length?recipe.steps:[''];builderTimers=builderSteps.map(()=>0);photoData=recipe.photoUri||'';const preview=$('[data-photo-preview]');preview.hidden=!photoData;preview.style.backgroundImage=photoData?`url('${photoData}')`:'';renderBuilderRows();$('[data-import-dialog]').close();showView('create');toast(`${builderIngredients.length} ${tr('ingredients and','ingrediënten en')} ${builderSteps.length} ${tr('steps imported.','stappen geïmporteerd.')}`)}

function compressImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const image=new Image();image.onerror=reject;image.onload=()=>{const scale=Math.min(1,1200/image.width,675/image.height),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.72))};image.src=reader.result};reader.readAsDataURL(file)})}
async function importPhotoText(file){$('[data-import-status]').textContent=tr('Reading photo… this can take a minute.','Foto lezen… dit kan een minuut duren.');const{createWorker}=await import('https://cdn.jsdelivr.net/npm/tesseract.js@6/+esm');const worker=await createWorker(['eng','nld']);const result=await worker.recognize(file);await worker.terminate();return result.data.text}

// Navigation and common controls
$$('[data-auth-mode]').forEach(button=>button.onclick=()=>setAuthMode(button.dataset.authMode));$$('[data-view]').forEach(button=>button.onclick=()=>showView(button.dataset.view));$$('[data-jump]').forEach(button=>button.onclick=()=>showView(button.dataset.jump));$$('[data-toggle-language]').forEach(button=>button.onclick=()=>{locale=locale==='en'?'nl':'en';applyLocale()});$('[data-mobile-menu]').onclick=()=>$('.sidebar').classList.toggle('is-open');$('[data-sign-out]').onclick=()=>signOut(auth);$('[data-force-sync]').onclick=()=>saveData(true).then(()=>toast(tr('Cloud data synchronized.','Cloudgegevens gesynchroniseerd.')));$('[data-copy-code]').onclick=async()=>{await navigator.clipboard.writeText($('[data-friend-code]').textContent);toast(tr('Friend code copied.','Vriendencode gekopieerd.'))};

$('[data-auth-form]').onsubmit=async event=>{event.preventDefault();if(!configured){$('[data-auth-error]').textContent='The MauGainZ account server is not configured.';return}const data=new FormData(event.currentTarget),email=String(data.get('email')||'').trim(),password=String(data.get('password')||''),displayName=String(data.get('displayName')||'').trim();$('[data-auth-error]').textContent='';$('[data-auth-submit]').disabled=true;try{if(authMode==='signup'){if(displayName.length<2)throw new Error('Choose a display name.');const result=await createUserWithEmailAndPassword(auth,email,password);await updateProfile(result.user,{displayName});await ensureProfile(result.user)}else await signInWithEmailAndPassword(auth,email,password)}catch(error){$('[data-auth-error]').textContent=String(error?.message||'Could not continue.').replace(/^Firebase:\s*/i,'').replace(/\(auth\/.+?\)\.?/i,'').trim()}finally{$('[data-auth-submit]').disabled=false}};
$('[data-reset-password]').onclick=async()=>{const email=$('[data-auth-form] [name="email"]').value.trim();if(!email){$('[data-auth-error]').textContent='Enter your email first.';return}try{await sendPasswordResetEmail(auth,email);toast('Password reset email sent.')}catch{$('[data-auth-error]').textContent='Could not send the reset email.'}};

// Diary
$('[data-diary-date]').onchange=event=>{diaryDate=event.target.value||localDate();renderDiary()};$$('[data-diary-mode]').forEach(button=>button.onclick=()=>{diaryMode=button.dataset.diaryMode;setDiaryMode()});$('[data-food-form]').onsubmit=event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),amount=Math.max(.1,num(data.get('amount'))),meal=String(data.get('meal'));if(diaryMode==='recipe'){const recipe=payload.recipes.find(item=>item.id===String(data.get('recipeId')));if(recipe)addRecipeToDiary(recipe,diaryDate,meal,amount);return}const name=String(data.get('name')||'').trim();if(!name){toast(tr('Enter a product name.','Vul een productnaam in.'));return}payload.diaryEntries.unshift({id:id('diary'),date:diaryDate,meal,source:'product',name,amount,unit:String(data.get('unit')),macros:{calories:num(data.get('calories')),protein:num(data.get('protein')),carbs:num(data.get('carbs')),fat:num(data.get('fat')),fiber:num(data.get('fiber'))},createdAt:Date.now()});form.reset();form.amount.value=1;commit(tr('Added to diary.','Toegevoegd aan dagboek.'))};$('[data-use-library]').onclick=()=>openLibraryPicker('diary');

// Recipes and builder
$('[data-recipe-search]').oninput=renderRecipes;$('[data-recipe-sort]').onchange=renderRecipes;$('[data-recipe-category]').onchange=renderRecipes;$('[data-recipe-form]').onsubmit=event=>{event.preventDefault();const recipe=formRecipe();if(!recipe.title||!recipe.ingredients.length){toast(tr('Add a name and at least one ingredient.','Voeg een naam en minstens één ingrediënt toe.'));return}const existing=payload.recipes.find(item=>item.id===recipe.id);if(existing)Object.assign(recipe,{favorite:existing.favorite,createdAt:existing.createdAt});payload.recipes=existing?payload.recipes.map(item=>item.id===recipe.id?recipe:item):[recipe,...payload.recipes];commit(tr('Recipe saved and synchronized.','Recept opgeslagen en gesynchroniseerd.'));resetBuilder();showView('recipes')};$('[data-reset-recipe]').onclick=resetBuilder;$('[data-add-ingredient]').onclick=()=>{builderIngredients.push(blankIngredient());renderBuilderRows()};$('[data-add-step]').onclick=()=>{builderSteps.push('');builderTimers.push(0);renderBuilderRows()};$('[data-servings-minus]').onclick=()=>scaleServings(-1);$('[data-servings-plus]').onclick=()=>scaleServings(1);$('[data-calculate-macros]').onclick=calculateBuilderMacros;$('[data-search-product]').onclick=()=>openProductSearch('builder');$('[data-use-library-builder]').onclick=()=>openLibraryPicker('builder');$('[data-add-category]').onclick=()=>{const input=$('[data-recipe-form] [name="newCategory"]'),name=input.value.trim();if(!name)return;if(!categories().some(item=>norm(item)===norm(name)))payload.customCategories.push({name,color:'#D2A74A',icon:'nutrition-outline'});input.value='';renderBuilderSelects();$('[data-recipe-form] [name="category"]').value=name;commit(tr('Category added.','Categorie toegevoegd.'))};$$('[data-collapse]').forEach(button=>button.onclick=()=>button.closest('.collapsible').classList.toggle('is-collapsed'));$('[data-recipe-form] [name="photo"]').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;photoData=await compressImage(file);const preview=$('[data-photo-preview]');preview.hidden=false;preview.style.backgroundImage=`url('${photoData}')`};$('[data-close-recipe]').onclick=()=> $('[data-recipe-dialog]').close();$('[data-close-cooking]').onclick=()=> $('[data-cooking-dialog]').close();

// Planning and performance
$('[data-plan-form]').onsubmit=event=>{event.preventDefault();const data=new FormData(event.currentTarget);payload.plans.push({id:id('plan'),date:String(data.get('date')),meal:String(data.get('meal')),recipeId:String(data.get('recipeId')),tag:String(data.get('tag')||'').trim()||undefined});commit(tr('Meal added to plan.','Maaltijd toegevoegd aan planning.'));event.currentTarget.tag.value=''};$('[data-shopping-form]').onsubmit=event=>{event.preventDefault();const name=new FormData(event.currentTarget).get('name').trim();if(name)payload.shopping.push({id:id('shop'),name,amount:'',unit:'',checked:false});event.currentTarget.reset();commit()};$('[data-generate-shopping]').onclick=()=>{const existing=new Set(payload.shopping.filter(item=>!item.checked).map(item=>norm(item.name))),plannedIds=payload.plans.map(item=>item.recipeId);plannedIds.forEach(recipeId=>payload.recipes.find(recipe=>recipe.id===recipeId)?.ingredients.forEach(item=>{if(!existing.has(norm(ingredientName(item))))payload.shopping.push({id:id('shop'),name:ingredientName(item),amount:item.amount,unit:item.unit,checked:false,recipeId})}));commit(tr('Shopping list generated from your plan.','Boodschappenlijst gemaakt vanuit je planning.'))};$('[data-target-form]').onsubmit=event=>{event.preventDefault();const data=new FormData(event.currentTarget),target={weekday:selectedTargetDay,calories:num(data.get('calories')),protein:num(data.get('protein')),carbs:num(data.get('carbs')),fat:num(data.get('fat')),fiber:30};payload.dailyTargets=[...payload.dailyTargets.filter(item=>item.weekday!==selectedTargetDay),target];commit(tr('Daily target saved.','Dagdoel opgeslagen.'))};$('[data-weight-form]').onsubmit=event=>{event.preventDefault();const data=new FormData(event.currentTarget),date=String(data.get('date')),weight=num(data.get('weight'));if(weight>0)payload.weights=[{id:id('weight'),date,weightKg:weight},...payload.weights.filter(item=>item.date!==date)];commit(tr('Weight entry saved.','Gewicht opgeslagen.'))};$('[data-vitamin-form]').onsubmit=event=>{event.preventDefault();const data=new FormData(event.currentTarget),name=String(data.get('name')).trim();if(name)payload.vitamins.push({id:id('vitamin'),name,dose:String(data.get('dose')||'').trim(),takenDates:[]});event.currentTarget.reset();commit()};

// Ingredient library, product database and scanner
$$('[data-library-tab]').forEach(button=>button.onclick=()=>{libraryTab=button.dataset.libraryTab;editingIngredient=null;$('[data-ingredient-editor]').innerHTML='<div class="empty-state">Choose an ingredient or add your own product.</div>';renderIngredientLibrary()});$('[data-ingredient-search]').oninput=renderIngredientLibrary;$('[data-new-ingredient]').onclick=()=>{editingIngredient={id:'',name:'',nameNl:'',brand:'',barcode:'',baseUnit:'g',servingSize:100,nutritionPer100:emptyMacros()};libraryTab='mine';renderIngredientLibrary();renderIngredientEditor()};$('[data-search-off]').onclick=()=>openProductSearch('library');$$('[data-scan-purpose]').forEach(button=>button.onclick=()=>openScanner(button.dataset.scanPurpose));$('[data-close-product]').onclick=()=> $('[data-product-dialog]').close();$('[data-product-search-form]').onsubmit=async event=>{event.preventDefault();const term=String(new FormData(event.currentTarget).get('query')||'').trim();if(!term)return;$('[data-product-status]').textContent=tr('Searching Belgian products…','Belgische producten zoeken…');try{const items=await searchProducts(term);$('[data-product-status]').textContent=`${items.length} ${tr('products found','producten gevonden')}`;renderProductResults(items)}catch{$('[data-product-status]').textContent=tr('Could not reach Open Food Facts. Try again.','Open Food Facts niet bereikbaar. Probeer opnieuw.')}};$('[data-close-scanner]').onclick=closeScanner;$('[data-manual-barcode-form]').onsubmit=event=>{event.preventDefault();const code=String(new FormData(event.currentTarget).get('barcode')||'').trim();if(code)processBarcode(code)};$('[data-close-library-picker]').onclick=()=> $('[data-library-picker]').close();$('[data-picker-search]').oninput=renderPicker;

// Import
$('[data-open-import]').onclick=()=> $('[data-import-dialog]').showModal();$('[data-close-import]').onclick=()=> $('[data-import-dialog]').close();$$('[data-import-mode]').forEach(button=>button.onclick=()=>{const mode=button.dataset.importMode;$$('[data-import-mode]').forEach(item=>item.classList.toggle('is-active',item===button));$('[data-import-url]').hidden=mode!=='url';$('[data-import-text]').hidden=mode!=='text';$('[data-import-photo]').hidden=mode!=='photo';$('[data-import-form]').dataset.mode=mode});$('[data-import-form]').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,mode=form.dataset.mode||'url',data=new FormData(form);$('[data-import-status]').textContent=tr('Importing…','Importeren…');try{let recipe;if(mode==='text')recipe=parseRecipeText(String(data.get('text')||''));else if(mode==='photo'){const file=form.photo.files?.[0];if(!file)throw new Error('photo');recipe=parseRecipeText(await importPhotoText(file))}else{const url=String(data.get('url')||'').trim();if(!url)throw new Error('url');let response;try{response=await fetchTimed(url,7000)}catch{}if(!response?.ok)try{response=await fetchTimed(`https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`,7000)}catch{}if(!response?.ok)throw new Error('network');const html=await response.text();recipe=extractJsonLd(html,url)||parseRecipeText(new DOMParser().parseFromString(html,'text/html').body.innerText)}if(!recipe.ingredients?.length&&!recipe.steps?.length)throw new Error('empty');applyImportedRecipe(recipe)}catch(error){console.error(error);$('[data-import-status]').textContent=tr('Import failed. Paste the recipe text instead, or try another image.','Import mislukt. Plak de recepttekst of probeer een andere foto.')}};

// Friends and settings
$('[data-friend-form]').onsubmit=async event=>{event.preventDefault();const code=String(new FormData(event.currentTarget).get('code')||'').replace(/[^a-z0-9]/gi,'').toUpperCase();if(!code)return;try{const codeDocument=await getDoc(doc(db,'friendCodes',code));if(!codeDocument.exists())throw new Error('not-found');const target=codeDocument.data();if(target.uid===currentUser.uid)throw new Error('self');await setDoc(doc(db,'friendRequests',`${currentUser.uid}_${target.uid}`),{fromUid:currentUser.uid,fromName:currentUser.displayName||currentUser.email.split('@')[0],fromCode:friendCodeFor(currentUser.uid),toUid:target.uid,toName:target.displayName,toCode:code,status:'pending',createdAt:serverTimestamp()});event.currentTarget.reset();toast(tr('Friend request sent.','Vriendschapsverzoek verzonden.'))}catch(error){toast(error.message==='self'?tr('That is your own code.','Dat is je eigen code.'):tr('Friend code not found.','Vriendencode niet gevonden.'))}};$('[data-share-form]').onsubmit=async event=>{event.preventDefault();const data=new FormData(event.currentTarget),friendUid=String(data.get('friend')||''),recipe=payload.recipes.find(item=>item.id===String(data.get('recipe')||'')),friend=connections.find(item=>item.status==='accepted'&&(item.fromUid===friendUid||item.toUid===friendUid));if(!friendUid||!recipe||!friend)return;await setDoc(doc(db,'recipeShares',`${currentUser.uid}_${friendUid}_${Date.now()}`),{fromUid:currentUser.uid,fromName:currentUser.displayName||currentUser.email.split('@')[0],toUid:friendUid,recipeJson:JSON.stringify(recipe),status:'pending',createdAt:serverTimestamp()});toast(tr('Recipe shared.','Recept gedeeld.'));event.currentTarget.reset()};$('[data-goals-form]').onsubmit=event=>{event.preventDefault();const data=new FormData(event.currentTarget);payload.goals={weightKg:num(data.get('weightKg')),goal:String(data.get('goal')),calories:num(data.get('calories')),protein:num(data.get('protein')),carbs:num(data.get('carbs')),fat:num(data.get('fat'))};commit(tr('Goals saved.','Doelen opgeslagen.'))};$('[data-unit-system]').onchange=event=>{payload.unitSystem=event.target.value;commit()};$('[data-category-form]').onsubmit=event=>{event.preventDefault();const name=String(new FormData(event.currentTarget).get('name')||'').trim();if(name&&!categories().some(item=>norm(item)===norm(name)))payload.customCategories.push({name,color:'#D2A74A',icon:'nutrition-outline'});event.currentTarget.reset();commit();renderBuilderSelects()};$('[data-export-backup]').onclick=()=>{const text=JSON.stringify(payload,null,2);$('[data-backup-text]').value=text;const blob=new Blob([text],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`MauGainZ-backup-${localDate()}.json`;link.click();URL.revokeObjectURL(link.href)};$('[data-import-backup]').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data.recipes))throw new Error();payload=normalizePayload(data);await saveData(true);renderAll();toast(tr('Backup imported.','Back-up geïmporteerd.'))}catch{toast(tr('Invalid backup file.','Ongeldig back-upbestand.'))}};

if(['127.0.0.1','localhost'].includes(location.hostname)&&new URLSearchParams(location.search).has('preview')){previewMode=true;currentUser={uid:'preview-user',email:'preview@maugainz.local',displayName:'MauGainZ Athlete'};payload=emptyPayload();payload.recipes=[{id:'preview-recipe',title:'Power Chicken Bowl',titleNl:'Power Kip Bowl',subtitle:'Lean, loaded & ready to perform',category:'Post-workout',prepTime:25,servings:2,accent:'#D2A74A',favorite:true,createdAt:Date.now(),ingredients:[blankIngredient({name:'Chicken breast',nameNl:'Kipfilet',amount:'300',unit:'g'}),blankIngredient({name:'Basmati rice',nameNl:'Basmatirijst',amount:'160',unit:'g'}),blankIngredient({name:'Broccoli',amount:'200',unit:'g'})],steps:['Cook the rice until fluffy.','Season and sear the chicken.','Steam the broccoli and build the bowl.'],macros:{calories:684,protein:62,carbs:74,fat:14,fiber:8}}];payload.diaryEntries=[{id:'preview-diary',date:localDate(),meal:'Lunch',source:'recipe',name:'Power Chicken Bowl',amount:1,unit:'portion',macros:payload.recipes[0].macros,createdAt:Date.now(),recipeId:'preview-recipe'}];payload.savedIngredients=[{id:'preview-skyr',name:'Protein Skyr',nameNl:'Proteïne Skyr',brand:'MauGainZ',baseUnit:'g',servingSize:200,nutritionPer100:{calories:64,protein:11,carbs:4,fat:.2,fiber:0}}];$('[data-loading]').hidden=true;$('[data-auth]').hidden=true;$('[data-dashboard]').hidden=false;$$('[data-user-name],[data-settings-name]').forEach(node=>node.textContent='MauGainZ Athlete');$$('[data-user-email],[data-settings-email]').forEach(node=>node.textContent='preview@maugainz.local');$$('[data-avatar],[data-settings-avatar]').forEach(node=>node.textContent='M');$('[data-friend-code]').textContent='PREVIEW1';resetBuilder();$('[data-diary-date]').value=diaryDate;$('[data-plan-form] [name="date"]').value=diaryDate;$('[data-weight-form] [name="date"]').value=diaryDate;applyLocale()}else if(!configured){$('[data-loading]').hidden=true;$('[data-auth]').hidden=false;$('[data-auth-error]').textContent='The MauGainZ account server is being connected. Please try again shortly.'}else{app=initializeApp(config);auth=getAuth(app);db=getFirestore(app);onAuthStateChanged(auth,async user=>{$('[data-loading]').hidden=true;if(!user){openAuth();return}try{const profile=await ensureProfile(user);openDashboard(user,profile)}catch(error){console.error(error);openAuth();$('[data-auth-error]').textContent='Could not open your account data.'}})}
